mapper.select:
select f.fine_id, f.borrow_id, f.user_id, f.book_id, f.overdue_days, f.fine_amount, f.fine_status, f.pay_time, bk.book_name, u.user_name, (select b.borrow_status from lib_borrow b where b.borrow_id = f.borrow_id) as borrow_status, f.create_by, f.create_time, f.update_by, f.update_time, f.remark from lib_fine f left join lib_book bk on f.book_id = bk.book_id left join lib_user u on f.user_id = u.user_id
and f.user_id = #{userId} and f.book_id = #{bookId} and f.borrow_id = #{borrowId} and bk.book_name like concat('%', #{bookName}, '%') and u.user_name like concat('%', #{userName}, '%') and f.fine_status = #{fineStatus}
order by f.create_time desc

mapper.update:
update lib_fine
borrow_id = #{borrowId}, user_id = #{userId}, book_id = #{bookId}, overdue_days = #{overdueDays}, fine_amount = #{fineAmount}, fine_status = #{fineStatus}, pay_time = #{payTime}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark},
where fine_id = #{fineId}
